    "phone.send": "भेजें",
    "phone.thinking": "सोच रहा हूँ",
    "pillar1.body": "एयरप्लेन मोड? मेट्रो? फ़्लाइट? कोई फ़र्क़ नहीं। इन्फ़रेन्स आपके SoC पर होता है, कभी किसी और के सर्वर पर नहीं।",
    "pillar1.title": "पूरी तरह ऑफ़लाइन",
    "pillar2.body": "पुनः उपयोग योग्य सिस्टम प्रॉम्प्ट एक बार सहेजें और हर मॉडल के लिए सही चुनें। हर सेशन में टोन, भूमिका और आउटपुट फ़ॉर्मेट को संगत रखें।",
    "pillar2.title": "आपकी भूमिकाएँ, सहेजी हुईं",
    "pillar3.body": "Temperature, Top-P, Top-K, Min-P, repetition penalty, seed, संदर्भ का आकार — हर मॉडल अपनी सेटिंग्स याद रखता है।",
    "pillar3.title": "हर पैरामीटर ट्यून करें",
    "pillar4.body": "मॉडल कई गीगाबाइट के होते हैं। किसी भी फ़ोल्डर में डाउनलोड करें — आंतरिक स्टोरेज, SD कार्ड या बाहरी ड्राइव। कभी भी जगह बदलें।",
    "pillar4.title": "कहीं भी सहेजें",
    "pillars.eyebrow": "ऑन-डिवाइस क्यों",
    "pillars.sub": "मॉडल के वज़न आपके फ़ोन में रहते हैं। प्रॉम्प्ट, ड्राफ़्ट और जवाब किसी सर्वर तक नहीं पहुँचते — पहुँचने को सर्वर ही नहीं है।",
    "pillars.title": "बनावट से ही निजी। डिज़ाइन से ही तेज़।",
    "prompts.card1": "आप एक संक्षिप्त सहायक हैं। हमेशा फ़्रेंच में उत्तर दें।",
    "prompts.card2": "सीनियर Kotlin समीक्षक — बग बताएँ, मुहावरेदार सुधार सुझाएँ, संक्षिप्त रहें।",
